import {
  companyService as baseCompanyService,
  type CompanyItem as BaseCompanyItem,
  type ActiveCompanyItem,
} from '@linm-soft-org/linm-web-common-components';

export type { ActiveCompanyItem };

/** Extended — GrepKeys/RefKeys sao kê (BE CompanyDetailDto; common publish later). */
export type CompanyItem = BaseCompanyItem & {
  grepKeys?: string;
  refKeys?: string;
};

export type CreateCompanyRequest = Parameters<typeof baseCompanyService.create>[0] & {
  grepKeys?: string;
  refKeys?: string;
};

export type UpdateCompanyRequest = Parameters<typeof baseCompanyService.update>[1] & {
  grepKeys?: string;
  refKeys?: string;
};

export const companyService = {
  getAll: (): Promise<CompanyItem[]> =>
    baseCompanyService.getAll() as Promise<CompanyItem[]>,
  getById: (id: string): Promise<CompanyItem> =>
    baseCompanyService.getById(id) as Promise<CompanyItem>,
  getActiveList: baseCompanyService.getActiveList,
  getByCode: baseCompanyService.getByCode,
  getPublicById: baseCompanyService.getPublicById,
  create: (payload: CreateCompanyRequest): Promise<CompanyItem> =>
    baseCompanyService.create(payload as Parameters<typeof baseCompanyService.create>[0]) as Promise<CompanyItem>,
  update: (id: string, payload: UpdateCompanyRequest): Promise<CompanyItem> =>
    baseCompanyService.update(
      id,
      payload as Parameters<typeof baseCompanyService.update>[1],
    ) as Promise<CompanyItem>,
  toggleStatus: (id: string): Promise<CompanyItem> =>
    baseCompanyService.toggleStatus(id) as Promise<CompanyItem>,
  delete: baseCompanyService.delete,
};
